TITLE = "Jamaica are going to Brazil, and it's their third Women's World Cup in a row"
TAG = "Flavor Sports"
H1 = "Jamaica are going to Brazil, and it's their third Women's World Cup in a row"
DEK = "The Reggae Girlz beat Costa Rica 3-0 in Texas without their head coach, and Bunny Shaw had a big hand in all three goals."
META = "Flavor Sports · 28 Nov 2026 · 3 min read"
LEAD = ("img/sp-jamaica-qualified.jpg", "Jamaica's players celebrate with the World Cup qualification banner in Mansfield, Texas", "Jamaica Football Federation / @jff_football")

BODY = [
("p", "Jamaica's place at the 2027 FIFA Women's World Cup in Brazil is confirmed. The Reggae Girlz beat Costa Rica 3-0 in the quarterfinals of the Concacaf W Championship on Friday 27 November at Texas Health Mansfield Stadium in Mansfield, Texas. Kick-off was 5pm Jamaica time, which was 1am on Saturday in Kenya."),
("p", "The four quarterfinal winners all qualify directly for the World Cup. That gave the game one simple stake: win and you're in."),
("h2", "", "How the goals ", "came"),
("p", "Jamaica went ahead in the 16th minute through Jody Brown and took that lead into half-time. The second goal came in the 59th minute. Khadija \"Bunny\" Shaw played a low ball across the face of goal, and Kiki Van Zanten finished it at the back post. Six minutes later, Shaw scored one of her own with a direct free kick that took a deflection off the Costa Rican wall."),
("img", "img/sp-jamaica-team-fans.jpg", "The Reggae Girlz celebrate with their fans after the win", "Jamaica Football Federation / @jff_football"),
("p", "It was Shaw's 50th game for Jamaica. She came into this tournament as one of the biggest names in the women's game, a Manchester City forward who was a Ballon d'Or finalist this year. Here she scored one and set up another, and she captained the side through all of it."),
("facts", [("Score", "Jamaica 3-0 Costa Rica"), ("Venue", "Texas Health Mansfield Stadium, Mansfield, Texas"), ("Jamaica scorers", "Brown 16', Van Zanten 59', Shaw 65'"), ("Next", "Semifinal vs USA, Tuesday 1 December")]),
("h2", "", "No head coach ", "on the touchline"),
("p", "Jamaica did this without their head coach. Hubert Busby Jr., who is Canadian, was refused entry into the United States because his US green card application is still being processed. Assistant coach Deon Burton stepped in to lead the team. On the evidence of the scoreline, the players didn't let it throw them."),
("img", "img/sp-jamaica-laughing.jpg", "Jamaica's players share the moment on the pitch", "Jamaica Football Federation / @jff_football"),
("h2", "", "From first-timers ", "to regulars"),
("p", "Jamaica's first Women's World Cup was France 2019, a debut that came with backing from the Marley family. Four years later, in 2023, they reached the round of 16. Brazil will be their third tournament in a row, and in this region only a few teams can now say that."),
("p", "Jamaica were also the first Concacaf team to qualify for Brazil 2027. The United States followed a few hours later, beating El Salvador 8-0 in the next quarterfinal at the same stadium, with Ashley Sanchez scoring a first-half hat-trick."),
("img", "img/sp-jamaica-four.jpg", "Jamaica's players in their World Cup qualified shirts", "Jamaica Football Federation / @jff_football"),
("h2", "", "What's ", "next"),
("p", "Qualifying is done, but the tournament in Texas goes on. Jamaica now play the USA in the semifinal on Tuesday 1 December, a chance to measure themselves against a four-time world champion before Brazil."),
]

